tion status(){try{const r=await fetch('/smart-toolz/api/trial.php?action=status&tool='+encodeURIComponent(slug),{cache:'no-store'});const d=await r.json();if(d.ok&&d.guest)set(d.remaining)}catch(e){}}async function consume(){try{const r=await fetch('/smart-toolz/api/trial.php?action=consume&tool='+encodeURIComponent(slug),{method:'POST',cache:'no-store'});const d=await r.json();if(d.ok&&d.guest){set(d.remaining);return true}if(d.reason==='trial_exhausted'){set(0);alert('Your 5 free trials for this tool are finished. Please login to continue using credits.');return false}return false}catch(e){alert('Unable to start the free trial right now.');return false}}let busy=false;document.addEventListener('submit',async e=>{const f=e.target;if(!(f instanceof HTMLFormElement)||!f.closest('main')||f.dataset.guestApproved==='1')return;e.preventDefault();if(busy)return;busy=true;if(await consume()){f.dataset.guestApproved='1';f.requestSubmit();f.dataset.guestApproved=''}busy=false},{capture:true});document.addEventListener('click',async e=>{const el=e.target.closest('main button,main input[type="submit"]');if(!el||el.closest('form')||el.dataset.guestApproved==='1'||el.disabled)return;e.preventDefault();if(busy)return;busy=true;if(await consume()){el.dataset.guestApproved='1';el.click();el.dataset.guestApproved=''}busy=false},{capture:true});status()})();</script>
